namespace Meloniq\GpOpenaiTranslate;

/**
 * Locale Instructions class.
 *
 * Provides locale-specific translation guidelines distilled from
 * translate.wordpress.org style guides via AI analysis.
 *
 * Generated from official WordPress translation team style guides at
 * https://{locale}.wordpress.org/team/handbook/ — see each locale's
 * glossary page for the source link.
 */
class Locale_Instructions {

	/**
	 * Get default locale-specific instructions.
	 *
	 * Actionable LLM directives distilled from translate.wordpress.org
	 * locale team style guides. Each entry was generated by an AI agent
	 * that fetched the official style guide page(s) and extracted only
	 * the rules that affect machine translation output.
	 *
	 * @return array<string, string> Locale slug => instruction string.
	 */
	public static function get_default_instructions(): array {
		return array(
			'de'    => 'Use informal register with lowercase „du" (not „Sie") as the default. Use German typographic quotation marks: „ (U+201E) to open and " (U+201C) to close. Replace & with „und". For numbers, use a period as thousands separator and a comma as decimal separator (e.g., 1.000.000 and 3,5). Dates follow DD.MM.YYYY order (e.g., „13. Juni 2013" or „13.06.2013"); do not add a leading zero to single-digit days. Use 24-hour time format separated by a colon (e.g., „9:00 Uhr", „21:00 Uhr"); convert English 12-hour formats (g:i a) to 24-hour (G:i). Replace the @ symbol in date/time format strings with a comma. Place the currency symbol after the amount with a non-breaking space (e.g., „20 €"). Insert a non-breaking space between numbers and units or percent signs (e.g., „40 %", „25 kg"). For UI labels and button text, use the infinitive (e.g., „Benutzer hinzufügen"). For instructional text, use the imperative du-form (e.g., „Drücke F1"), not infinitive constructions. In headings and titles, translate English gerunds or infinitives as nominalized verbs without an article (e.g., „Adding Users" → „Hinzufügen von Benutzern"); do not end titles with a period. Translate „About X" as „Informationen zu X" and „How to…" / „To…" as „So…". Use generic masculine for user-facing product text (e.g., „Benutzer", „Administrator"), not gendered forms, Gendersternchen, or colons. Do not anthropomorphize software — avoid attributing feelings, intentions, or intelligence to programs. Do not translate plugin names, theme names, or brand names (always write „WordPress", never localize it). Preserve all placeholders (%s, %d, %1$s, %(author)s) exactly — you may reorder them within the sentence but never translate or modify their content. Replace HTML entities for English curly quotes (&#8220; &#8221;) with their German equivalents (&#8222; &#8220;). Translate „e.g." as „z. B." and „i.e." as „d. h." with a non-breaking space between the letters. Avoid colloquialisms (use „für das" not „fürs", „noch einmal" not „nochmal"). Connect mixed German-English compound words with hyphens (e.g., „Block-Editor", „WordPress-Core"). Keep titles concise and avoid parenthetical insertions in headings.',

			'es'    => 'Use informal Spanish (Spain) register throughout: address the user as «tú» (e.g., «tu sitio», «haz clic»), never «usted». Always use Spanish angular quotation marks « » for quoted text, never " " or \' \'. Capitalize only the first word of UI labels and headings — do not replicate English Title Case (write «Subir archivo», not «Subir Archivo»). Translate contextually, not literally: produce natural Spanish phrasing with proper prepositions and articles (e.g., «Page Management Documentation» → «Documentación de la gestión de páginas»). Use gender-neutral constructions where possible: prefer «¿Seguro que quieres…?» over «¿Estás seguro/a…?». Always include inverted punctuation for questions and exclamations (¿…? and ¡…!). Do not translate plugin names, theme names, product names, or technical terms that the glossary marks untranslatable (e.g., ajax, array, blog, banner, bitrate, widget, shortcode). Translate «add» as «añadir» (never «agregar»), «authenticate/authentication» as «identificar/identificación» (never «autenticar»), «backup» as «copia de seguridad», «admin» as «administrador» (person) or «administración» (area), «about» as «acerca de» (preferred over «sobre»), and «bulk» as «por lotes» or «en lote» (never «en masa»). Replace references to «blog» with «sitio» unless the source specifically means a blog import. Preserve all placeholders (%s, %d, %1$s, {{tag}}, etc.) exactly as they appear, maintaining their position and order. Use the decimal comma and period as thousands separator for numbers following Spanish (Spain) conventions. Use 24-hour time format. Apply RAE orthographic rules for accents and spelling.',

			'es-mx' => 'Use informal second-person singular "tú" conjugations (e.g., "haz clic", "escribe", "elige"); never use "usted" or voseo ("vos"). Do not translate plugin names, theme names, or error strings that are variable names or codes — only translate error messages that are full sentences. Do not capitalize every word in titles or headings as English does; capitalize only the first word and proper nouns (e.g., "Users List" → "Lista de usuarios", not "Lista De Usuarios"). Use straight double quotation marks " " (comillas altas/inglesas) to highlight UI elements or avoid ambiguity; never use guillemets « », single quotes, or apostrophes as quotation marks. Always include inverted punctuation marks ¿ and ¡ at the start of questions and exclamations. Use comma , as the thousands separator and period . as the decimal separator. Format dates as day/month/year: "24 de diciembre de 2020" or "24/12/2020". Preserve all placeholders exactly as they appear in the source string — %s, %d, %1$s, etc. — without reordering, omitting, or translating them. Do not omit any words or phrases from the source string; translate the complete content. Use natural Mexican Spanish vocabulary and phrasing, avoiding peninsular Spanish idioms or terminology where regional usage differs.',

			'fr'    => 'Use formal « vous » register throughout. Apply French punctuation spacing: insert a non-breaking space before « : », « ; », « ? », « ! », « » », and « % »; insert a regular space after « « »; no space before « . », « , », or « … ». Use French guillemets « » for quotation marks, never straight or curly English quotes. Use the typographic curly apostrophe (\') not the straight apostrophe. For inclusive/epicene writing, prefer neutral formulations first (e.g., « les personnes » instead of gendered nouns), then combined forms (« les administrateurs et administratrices »), and only as a last resort use the point médian (« administrateur·ice·s »). Capitalize minimally — unlike English, use lowercase for everything except the first letter of a sentence, proper nouns, and acronyms; titles, button labels, and headings follow this rule (e.g., « Réglages du site » not « Réglages Du Site »). Always accent uppercase letters (« À », « É », « È ») except in acronyms. Write days and months in lowercase (« lundi », « mars »). Use a comma as decimal separator and a non-breaking space as thousands separator (« 1 000,50 »). Use the single ellipsis character « … » not three periods. Ordinals use superscript suffixes: « 1er », « 2e », « 3e ». Do not translate WordPress core terms that are proper nouns (e.g., « WordPress », « Gutenberg »), PHP function names, HTML tags, or placeholders like %s, %d, {{count}} — preserve them exactly. Keep all HTML markup, shortcodes, and printf-style format strings untouched and in their original position. End complete sentences with a period; omit terminal punctuation on UI labels and button text that are not full sentences.',

			'it'    => 'Use informal register with second-person singular "tu" verbs (e.g., "Seleziona", "Inserisci"), never third-person, plural, or infinitive forms. Use active voice ("il plugin aggiornerà i valori", not "i valori saranno aggiornati dal plugin"). Never translate "Please" or humanize software messages — programs do not speak. Do not apply English Title Case; capitalize only sentence-initial words, proper nouns, and UI element names when referencing them in instructions. Write day and month names in lowercase (lunedì, gennaio). Format dates as day–month–year (27 maggio 2023) and times in 24-hour format without AM/PM; convert date-format codes accordingly (e.g., "M j, Y g:i A" → "j M Y H:i"). Do not use the Oxford comma ("uno, due e tre", not "uno, due, e tre"). Use exactly three dots for ellipsis (…). Place no space before punctuation or inside parentheses/quotation marks. Use proper accented characters (È, not E\'); distinguish grave (è, à, ò, ù) from acute (é in perché, poiché, né, sé). English loanwords kept in Italian lose the plural "s" — use the article to indicate number (il plugin, i plugin). Translate English "-ing" progress verbs as noun + "in corso…" (e.g., "Loading templates" → "Caricamento dei template in corso…"). Translate "&" used as a conjunction to "e". Never translate placeholders (%s, %1$s, %2$s, ###SITEURL###), HTML tags, theme/plugin names, author names, or changelog entries — copy them verbatim. Translate ALT and TITLE attribute values inside HTML tags. Replace wordpress.org URLs with it.wordpress.org equivalents when the Italian page exists. Adapt idioms and wordplay to Italian cultural equivalents rather than translating literally. Keep technical terms untranslated when no established Italian equivalent exists.',

			'ja'    => 'Use desu/masu (敬体) form for descriptive sentences and plain form (常体) for headings, list items, and button labels; omit trailing「します」/「する」on button labels. Use fullwidth period「。」and comma「、」for Japanese punctuation; use halfwidth for all alphanumeric characters, parentheses, question marks, and exclamation marks. Insert a halfwidth space between halfwidth characters and fullwidth characters, except: no space around「」『』。、, no space before colon (:), and no space adjacent to halfwidth numbers (e.g., "1件のコメント" not "1 件のコメント"). Treat placeholders (%s, %d, %1$s, %2$s) as halfwidth numbers — no space between a placeholder and adjacent Japanese text, and preserve the exact count and type of placeholders from the source string. Use halfwidth parentheses ( ) with a halfwidth space before the opening and after the closing paren, but no spaces inside. Use「」for quoting UI element names (menu items, button labels) and for translating double-quoted terms that appear in Japanese; keep ASCII double quotes for English-only terms like domain names or function names. For katakana loanwords, add the long vowel mark「ー」when the word including it is 4 characters or fewer (ユーザー, サーバー); omit it at 5+ characters (コンパイラ, インストーラ), except words ending in a palatalized sound or established convention (コンピューター, エディター). Do not use nakaguro「・」in katakana compounds; use「の」to separate elements if clarity requires it. Do not translate brand names (WordPress), theme names (Twenty Twenty), or plugin names — keep them in English. Translate dates as Y年M月D日 format (e.g., 2014年1月1日). Avoid passive voice; prefer active constructions (「～しました」over「～されました」). Do not translate "Sorry, …" in error messages — drop it entirely. Avoid translating "You/Your" as「あなた」; use「お使いの」or omit. Write「ください」「すべて」「すでに」in hiragana, not kanji.',

			'pt-br' => 'Use an informal but polite register with "você" (never "tu"); prefer simpler synonyms like "usar" over "utilizar" and "ter" over "possuir". Avoid gender-specific language wherever possible by rewriting sentences to be neutral (e.g., "Agradecemos a ajuda" instead of "Obrigado(a) pela ajuda"). Apply Portuguese capitalization rules: only capitalize the first word of a sentence/heading and proper nouns — never title-case headings as in English. Write months (janeiro, maio), languages (português, alemão), and demonyms (brasileiro) in lowercase. Use period as thousands separator and comma as decimal separator (1,500 → 1.500; 1.5 → 1,5). Format full dates as "27 de maio de 2003" (day month year) and short dates as dd/mm/YYYY. Use 24-hour time format (18:30) instead of AM/PM. Translate action verbs on buttons and links in the infinitive form ("Update" → "Atualizar"). Convert English gerunds to nouns when naming an action ("Printing new copies" → "Impressão de novas cópias"), use gerund only for actions in progress ("Imprimindo…"), and for section headings use "Como + infinitive". Avoid compound gerund forms ("vai estar escrevendo" → "vai escrever"). Omit "please" and "successfully" when they add no information in Portuguese. Drop unnecessary subject pronouns that English requires but Portuguese does not. Replace "#" with "nº" when it means "number". Never translate plugin names, theme names, or brand names; preserve brand casing exactly (WordPress, WooCommerce). Preserve all placeholders (%s, %d, %1$s, %2$d, ###CUSTOMER###, etc.) exactly as they appear, and do not insert spaces around inline HTML tags like <br>. Do not add emojis or other elements not present in the source string. Keep translations concise, especially for buttons and menus, aiming to stay within 20–30% length increase of the original.',

			'ro'    => 'Use informal register, addressing the user with 2nd person singular (tu). For buttons and single actions, use imperative mood, 2nd person singular (e.g., "Salvează", "Publică"). When the application describes its own actions, use 1st person singular (e.g., "Încarc pagina…", "Am actualizat articolul."). Avoid all gender references: translate "Are you sure?" as "Sigur?" not "Ești sigur?". Always use correct Romanian diacritics with comma-below: Ăă, Îî, Ââ, Șș, Țț — never cedilla variants Şş, Ţţ or tilde Ãã. Use Romanian quotation marks: „ (U+201E) to open, " (U+201D) to close. Do not capitalize interior words in titles or headings as English does; capitalize only proper nouns, command names, page names, and button names; after a colon or dash, continue with lowercase. Translate "&" as "și" unless it is part of a proper name. Preserve all placeholders (%s, %d, %1$s, %2$s, ###USERNAME###, ===EMAIL===) exactly; their numbered order may be rearranged if Romanian syntax requires it. Preserve all HTML tags in their original form; use straight double quotes inside HTML attributes only. Punctuation has no preceding space but is followed by a space: applies to . ! ? , ; : ) and …; opening parenthesis has a space before but none after; hyphens and slashes have no surrounding spaces; em-dashes have a space on each side. Romanian has three plural forms: singular (1), few/plural (0, 2–19), and large plural (20+) which requires the preposition "de" before the noun (e.g., "25 de obiecte"). Use comma as decimal separator (3,14) and period as thousands separator (1.000, 10.000). Place a space between a number and its unit (3 m, 15 px) and between an amount and currency symbol after it (9 $). Date format is day.month.year (d.m.Y); time format is hour:minute (G:i) using 24-hour clock. Do not translate plugin names, theme names, author names, service names, variable names, "ltr", "no-subset", or "on/off" when used as setting attribute values. Do not localize URLs unless an official Romanian version exists.',

			'ru'    => 'Use informal «вы» (lowercase) to address the user — never «ты» or formal «Вы». Always use the letter «ё» where etymologically correct (e.g., «учётная запись», «щёлкнуть», «ещё»). Use French-style guillemets «» as quotation marks, with inner quotes using „" if nesting is needed. Do not translate plugin names, theme names, product/service names (Facebook, Twitter, Jetpack, Gutenberg, WooCommerce), proper nouns, or technical terms like cron, URL, URI, id; leave them in the original language, undeclined, and without quotation marks. Preserve all HTML tags, format placeholders (%s, %d, %1$s, %2$s), and shortcodes exactly as they appear in the source string; never translate or reorder numbered placeholders unless sentence structure requires it. Avoid unnecessary filler phrases like «вы должны», «вы можете» — rephrase directly. Prefer active voice and natural Russian word order. Translate similar strings with consistent wording — do not vary phrasing arbitrarily. Use 24-hour time format (H:i, not G:i a) for date/time format strings. Use a non-breaking space as the thousands separator and a comma as the decimal separator for numbers. Russian has three plural forms: one (1, 21, 31…), few (2–4, 22–24…), many (0, 5–20, 25–30…) — provide all three forms when the string uses plural functions.',

			'zh-cn' => 'Use full-width Chinese punctuation (，。！？：；) in Chinese text; use half-width punctuation only inside complete English sentences or special English names embedded within Chinese text. Use corner bracket quotation marks: 「…」 for single quotes and 『…』 for nested quotes — never use "…" or \'…\'. Insert a space between Chinese and English text, between Chinese and numbers, and between numbers and units (e.g., "共有 10 GB 的空间"), but do NOT add spaces between full-width punctuation and adjacent characters. Do not add a space between numbers and degree/percentage signs (90°, 15%). Use half-width (ASCII) digits, never full-width digits. Do not repeat punctuation marks for emphasis (use single ！ or ？, not ！！！ or ？？？). Preserve proper capitalization of English brand names and technical terms exactly as officially written (e.g., GitHub, WordPress, TypeScript, not github or GITHUB). For plugin names, theme names, and other proper nouns, translate them into natural Chinese where possible and append the original English name in parentheses on first occurrence only (e.g., "超级缓存（WP-Super-Cache）"); leave subsequent occurrences without the parenthetical. Do not translate placeholders like %s, %d, %1$s, or HTML tags — preserve them exactly. Adopt a clear, natural, and slightly formal register that reads as native Chinese, not translationese; aim for accuracy without distorting meaning, fluency without slavishly following English syntax, and elegance in word choice.',

			'zh-tw' => 'Use formal, rigorous register; never use casual or conversational tone, and downgrade superlative adjectives to moderate expressions. Do NOT translate: company names, product/service names, plugin/theme names (e.g. keep "Gutenberg", never 古騰堡), paid tier names (Pro, Premium), API names, code identifiers (HTML tags, CSS classes, function names, attribute names/values), foreign personal names, or changelog entries. Use full-width punctuation for Chinese sentences: commas ，, periods 。, question marks ？, exclamation marks ！, and enumeration commas 、 for listing same-level items. Keep half-width parentheses () in both UI and docs. For colons, use half-width : in UI strings but full-width ： in documentation. Mark clickable UI elements with half-width square brackets: [設定]. Never translate English passive voice into Chinese passive with 被; rephrase actively (e.g. "This file is deleted" → 「已刪除這個檔案」, not 「這個檔案被刪除」). Insert one half-width space between half-width characters (Latin letters, numbers) and full-width Chinese characters, but no space between half-width characters and full-width symbols. Use Arabic numerals for all numbers regardless of the English source format. When English words appear within Chinese text, use singular form with initial capital (e.g. Cookie, not cookies). Replace italic emphasis with bold; never use italic style in zh-TW. Use 《》 for website/publication names and 〈〉 for page/article titles. Use standard Taiwan IT terminology: 外掛 (not 插件), 佈景主題 (not 主題), 精選圖片 (not 特色圖片), 留言 (not 迴響). Preserve all placeholders, HTML tags, and variables exactly as they appear in the source string. Convert English exclamation marks to full-width periods 。 unless genuine exclamatory tone is warranted.',

			// Locales without official style guides — minimal directives.
			'hu'    => 'Avoid direct second-person address (neither informal nor formal). Reformulate into neutral plural construction.',
			'ko'    => 'Follow Korean foreign word notation standards (외래어 표기법). Use formal polite register (합니다체).',
			'ar'    => 'Use Modern Standard Arabic. Maintain right-to-left text direction markers where needed.',
			'tr'    => 'Use informal second-person singular (sen) register. Follow Turkish Language Association (TDK) spelling rules.',
			'sv'    => 'Use informal "du" address. Follow Swedish Language Council (Språkrådet) conventions.',
		);
	}

	/**
	 * Get locale-specific instructions for a given locale.
	 *
	 * Checks user overrides first, then falls back to defaults.
	 * If the exact locale has no instructions, tries the parent locale
	 * (e.g., es-mx falls back to es, fr-ca to fr, de-at to de).
	 *
	 * @param string $locale The locale slug.
	 *
	 * @return string The instructions string, or empty string if none.
	 */
	public static function get_instructions( string $locale ): string {
		// Check user overrides first.
		$overrides = get_option( 'gpoai_locale_instructions', array() );
		if ( is_array( $overrides ) && ! empty( $overrides[ $locale ] ) ) {
			return (string) $overrides[ $locale ];
		}

		// Check defaults for exact locale.
		$defaults = self::get_default_instructions();
		if ( ! empty( $defaults[ $locale ] ) ) {
			return $defaults[ $locale ];
		}

		// Fallback: try parent locale (e.g., es-ar → es, fr-ca → fr, de-ch → de).
		$parent = self::get_parent_locale( $locale );
		if ( $parent ) {
			// Check overrides for parent.
			if ( is_array( $overrides ) && ! empty( $overrides[ $parent ] ) ) {
				return (string) $overrides[ $parent ];
			}

			// Check defaults for parent.
			if ( ! empty( $defaults[ $parent ] ) ) {
				return $defaults[ $parent ];
			}
		}

		return '';
	}

	/**
	 * Get the parent locale slug for a regional variant.
	 *
	 * @param string $locale The locale slug.
	 *
	 * @return string|null The parent locale slug, or null.
	 */
	protected static function get_parent_locale( string $locale ): ?string {
		if ( strpos( $locale, '-' ) !== false ) {
			return explode( '-', $locale )[0];
		}

		return null;
	}
}
